  "sources": [
    {
      "source_handle": "P0583",
      "title": "Fecal microbiota transplantation plus immunotherapy in non-small cell lung cancer and melanoma: the phase 2 FMT-LUMINate trial",
      "year": "2026",
      "doi": "10.1038/s41591-025-04186-5",
      "paper_id": "071823eff68d7dbea395490dd4643170131b5f6a",
      "material_depth": "fulltext",
      "material_status": "resolved",
      "aliases": [],
      "study_summary_A": {
        "work_summary": "这是一项多中心、开放标签的II期临床试验（FMT-LUMINate），旨在评估单次口服胶囊FMT在启动ICI治疗前对原发性耐药患者的影响。研究纳入20名NSCLC患者和20名黑色素瘤患者。主要终点为NSCLC队列的客观缓解率（ORR）。结果显示，NSCLC队列ORR为80%，超过预设阈值；黑色素瘤队列ORR为75%。安全性方面，NSCLC组无3级及以上不良事件，而黑色素瘤组出现较早发的严重免疫相关不良反应（irAEs），特别是心肌炎，且与特定供体菌群有关。机制研究发现，响应者并非通过获得特定的供体菌株定植获益，而是通过显著清除基线存在的有害细菌物种（如Enterocloster和Clostridium属），从而降低色氨酸代谢途径活性并改善全身免疫微环境。",
        "approach": "研究设计为前瞻性、多中心、单臂II期临床试验。入组标准包括：NSCLC患者需PD-L1 TPS ≥50%且无一线可操作基因改变；黑色素瘤患者不限BRAF状态。所有患者在开始ICI治疗前一周内接受来自健康供体的单次FMT（口服胶囊）。主要终点是NSCLC队列的ORR。次要终点包括黑色素瘤ORR、1年无进展生存期（PFS）、总生存期（OS）、疾病控制率（DCR）及安全性。微生物组分析采用鸟枪法宏基因组测序，结合定量PCR和高通量培养组学验证细菌变化。此外，通过血浆代谢组学和流式细胞术分析免疫代谢景观，并在抗生素处理的荷瘤小鼠模型中通过回输“丢失”的细菌混合物来验证因果机制。",
        "key_findings": [
          {
            "conditions": "NSCLC患者接受FMT+抗PD-1",
            "finding": "ORR达到80%（16/20），满足主要终点；1年OS为100%；未观察到3级及以上与治疗相关的不良事件。"
          },
          {
            "conditions": "黑色素瘤患者接受FMT+抗PD-1+抗CTLA-4",
            "finding": "ORR为75%（15/20）；观察到较文献报道更早发生的严重免疫相关不良反应（irAEs），包括心肌炎；部分严重AEs与富含Prevotella的供体有关。"
          },
          {
            "conditions": "微生物组分析与临床响应关联",
            "finding": "响应者（R）与非响应者（NR）相比，在FMT后表现出显著更高的基线细菌物种丢失幅度。这种丢失主要由有害菌（如Enterocloster, Clostridium, Streptococcus）构成，而非供体菌株的定植。"
          },
          {
            "conditions": "机制验证（动物实验）",
            "finding": "在抗生素处理的小鼠中，将FMT响应者基线样本中丢失的有害细菌混合物重新引入，抵消了FMT联合ICI的抗肿瘤效应，证实消除有害菌是治疗获益的必要条件。"
          }
        ],
        "contribution_and_limits": [
          {
            "contribution": "提供了FMT联合ICI在NSCLC和黑色素瘤一线治疗中的临床活性证据，证实FMT可提高ORR。识别出“基线有害菌清除”作为潜在的药效学生物标志物，并揭示了其与色氨酸代谢抑制及CD8+ T细胞扩增的关联。",
            "limits": "研究为单臂设计，缺乏安慰剂对照，难以完全排除自然病程或其他混杂因素。样本量较小（每队列20人），限制了亚组分析和统计效力。黑色素瘤队列中观察到的严重毒性信号（如心肌炎）需要更大规模的随机试验进一步确认。供体选择对毒性的影响提示个体化差异，但具体筛选标准尚未确立。"
          }
        ],
        "problem_or_question": "尽管免疫检查点抑制剂改善了NSCLC和黑色素瘤的预后，但超过半数的患者存在原发性耐药。目前尚不清楚健康供体FMT联合抗PD-1（NSCLC）或抗PD-1联合抗CTLA-4（黑色素瘤）在一线治疗中的临床活性和安全性，以及FMT增强ICI疗效的人类机制。",
        "research_scope": "该研究针对晚期非小细胞肺癌（NSCLC）和皮肤黑色素瘤患者，评估健康供体粪便微生物群移植（FMT）联合一线免疫检查点抑制剂（ICI）治疗的临床疗效、安全性及机制。NSCLC队列接受抗PD-1单药治疗，黑色素瘤队列接受抗PD-1联合抗CTLA-4双免疫检查点抑制治疗。",
        "paper_kind": "empirical"
